1	"use client";
2	
3	import {
4	  createContext,
5	  useCallback,
6	  useContext,
7	  useEffect,
8	  useState,
9	  type ReactNode,
10	} from "react";
11	import {
12	  getWorkspace,
13	  importWorkspace as apiImportWorkspace,
14	  type ApiError,
15	  type ImportWorkspaceRequest,
16	  type LocalWorkspaceSummary,
17	  type WorkspaceDetail,
18	} from "@/services/workflow-backend";
19	import { buildImportLocalSummary } from "@/features/workspaces/lib/workspaceAdapter";
20	import {
21	  getLocalWorkspaceSummaries,
22	  getSelectedWorkspaceId,
23	  resolveBootstrapWorkspaceId,
24	  saveLocalWorkspaceSummary,
25	  removeLocalWorkspaceSummary,
26	  setSelectedWorkspaceId,
27	} from "@/services/local-workspace-store";
28	
29	export type WorkspaceContextValue = {
30	  summaries: LocalWorkspaceSummary[];
31	  selectedWorkspaceId: string | null;
32	  activeWorkspace: WorkspaceDetail | null;
33	  loadingWorkspace: boolean;
34	  workspaceError: ApiError | null;
35	  importingWorkspace: boolean;
36	  importError: ApiError | null;
37	
38	  selectWorkspace: (workspaceId: string) => void;
39	  importWorkspace: (body: ImportWorkspaceRequest) => Promise<void>;
40	  clearImportError: () => void;
41	  removeLocalSummary: (workspaceId: string) => void;
42	};
43	
44	const WorkspaceContext = createContext<WorkspaceContextValue | null>(null);
45	
46	export function WorkspaceProvider({ children }: { children: ReactNode }) {
47	  const [summaries, setSummaries] = useState<LocalWorkspaceSummary[]>([]);
48	  const [selectedWorkspaceId, setSelectedWorkspaceIdState] = useState<string | null>(null);
49	  const [activeWorkspace, setActiveWorkspace] = useState<WorkspaceDetail | null>(null);
50	  const [loadingWorkspace, setLoadingWorkspace] = useState(false);
51	  const [workspaceError, setWorkspaceError] = useState<ApiError | null>(null);
52	  const [importingWorkspace, setImportingWorkspace] = useState(false);
53	  const [importError, setImportError] = useState<ApiError | null>(null);
54	
55	  useEffect(() => {
56	    const storedSummaries = getLocalWorkspaceSummaries();
57	    const storedId = getSelectedWorkspaceId();
58	    setSummaries(storedSummaries);
59	
60	    const workspaceId = resolveBootstrapWorkspaceId(storedSummaries, storedId);
61	
62	    if (workspaceId) {
63	      setSelectedWorkspaceIdState(workspaceId);
64	      loadWorkspace(workspaceId);
65	    }
66	  }, []);
67	
68	  const loadWorkspace = useCallback((workspaceId: string) => {
69	    setLoadingWorkspace(true);
70	    setWorkspaceError(null);
71	    getWorkspace(workspaceId)
72	      .then((detail) => {
73	        setActiveWorkspace(detail);
74	        setLoadingWorkspace(false);
75	      })
76	      .catch((err: ApiError) => {
77	        setWorkspaceError(err);
78	        setLoadingWorkspace(false);
79	      });
80	  }, []);
81	
82	  const selectWorkspace = useCallback(
83	    (workspaceId: string) => {
84	      setSelectedWorkspaceIdState(workspaceId);
85	      setSelectedWorkspaceId(workspaceId);
86	      setActiveWorkspace(null);
87	
88	      const summary = summaries.find((s) => s.workspaceId === workspaceId);
89	      if (summary) {
90	        const updated: LocalWorkspaceSummary = {
91	          ...summary,
92	          last_opened_at: new Date().toISOString(),
93	        };
94	        saveLocalWorkspaceSummary(updated);
95	        setSummaries(getLocalWorkspaceSummaries());
96	      }
97	
98	      loadWorkspace(workspaceId);
99	    },
100	    [summaries, loadWorkspace],
101	  );
102	
103	  const importWorkspaceFn = useCallback(
104	    async (body: ImportWorkspaceRequest) => {
105	      setImportingWorkspace(true);
106	      setImportError(null);
107	      try {
108	        const detail = await apiImportWorkspace(body);
109	
110	        const summary = buildImportLocalSummary(detail, body, new Date().toISOString());
111	        saveLocalWorkspaceSummary(summary);
112	        setSelectedWorkspaceId(detail.id);
113	        setSummaries(getLocalWorkspaceSummaries());
114	        setSelectedWorkspaceIdState(detail.id);
115	        setActiveWorkspace(detail);
116	      } catch (err) {
117	        setImportError(err as ApiError);
118	        throw err;
119	      } finally {
120	        setImportingWorkspace(false);
121	      }
122	    },
123	    [],
124	  );
125	
126	  const clearImportError = useCallback(() => {
127	    setImportError(null);
128	  }, []);
129	
130	  const removeLocalSummary = useCallback((workspaceId: string) => {
131	    removeLocalWorkspaceSummary(workspaceId);
132	    setSummaries(getLocalWorkspaceSummaries());
133	    if (selectedWorkspaceId === workspaceId) {
134	      const remaining = getLocalWorkspaceSummaries();
135	      const next = remaining[0] ?? null;
136	      if (next) {
137	        setSelectedWorkspaceIdState(next.workspaceId);
138	        setSelectedWorkspaceId(next.workspaceId);
139	        loadWorkspace(next.workspaceId);
140	      } else {
141	        setSelectedWorkspaceIdState(null);
142	        setActiveWorkspace(null);
143	      }
144	    }
145	  }, [selectedWorkspaceId, loadWorkspace]);
146	
147	  return (
148	    <WorkspaceContext.Provider
149	      value={{
150	        summaries,
151	        selectedWorkspaceId,
152	        activeWorkspace,
153	        loadingWorkspace,
154	        workspaceError,
155	        importingWorkspace,
156	        importError,
157	        selectWorkspace,
158	        importWorkspace: importWorkspaceFn,
159	        clearImportError,
160	        removeLocalSummary,
161	      }}
162	    >
163	      {children}
164	    </WorkspaceContext.Provider>
165	  );
