    prevInitialDataRef.current = next;
    if (tick === 0) {
      setFeatures(adaptWorkspaceDetail(next));
      setLoading(false);
      setError(null);
    }
  });

  useEffect(() => {
    if (!workspaceId) {
      setFeatures([]);
      setLoading(false);
      setError(null);
      return;
    }

    if (tick === 0 && options.initialData) {
      setFeatures(adaptWorkspaceDetail(options.initialData));
      setLoading(false);
      return;
    }

    const id = ++requestId.current;
    let cancelled = false;
    setLoading(true);
    setError(null);

    getWorkspace(workspaceId)
      .then((detail) => {
        if (cancelled || requestId.current !== id) return;
        setFeatures(adaptWorkspaceDetail(detail));
        setError(null);
        setLoading(false);
      })
      .catch((err: unknown) => {
        if (cancelled || requestId.current !== id) return;
        setError(mapApiError(err));
        setLoading(false);
      });

    return () => {
      cancelled = true;
    };
  }, [workspaceId, tick]);

  return { features, loading, error, reload };
}

