    setTaskSearchQuery: vi.fn(),
    taskActiveFilters: opts.taskActiveFilters ?? { statuses: [] },
    setTaskActiveFilters: vi.fn(),
    featureSearchQuery: "",
    setFeatureSearchQuery: vi.fn(),
